templates.template:
.warextAudit-readOnly { margin-bottom: 15px; }
.warextAudit-stats { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px; margin: 15px 0; }
.warextAudit-stat { display: flex; flex-direction: column; padding: 14px; border: 1px solid @xf-borderColor; border-radius: @xf-borderRadiusMedium; background: @xf-contentBg; color: @xf-textColor; text-decoration: none; }
.warextAudit-stat:hover, .warextAudit-stat.is-active { border-color: @xf-linkColor; text-decoration: none; }
.warextAudit-statValue { font-size: 24px; font-weight: 700; line-height: 1; }
.warextAudit-statLabel { margin-top: 6px; color: @xf-textColorMuted; }
.warextAudit-stat--critical .warextAudit-statValue { color: @xf-errorColor; }
.warextAudit-filterForm { padding: 15px; }
.warextAudit-filterGrid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; }
.warextAudit-filterGrid label > span { display: block; margin-bottom: 5px; font-weight: 600; }
.warextAudit-filterActions { display: flex; gap: 8px; margin-top: 14px; }
.warextAudit-caseList { display: flex; flex-direction: column; }
.warextAudit-caseRow { display: flex; align-items: center; justify-content: space-between; gap: 15px; padding: 14px 15px; border-bottom: 1px solid @xf-borderColor; color: @xf-textColor; text-decoration: none; }
.warextAudit-caseRow:last-child { border-bottom: 0; }
.warextAudit-caseRow:hover { background: @xf-contentHighlightBg; text-decoration: none; }
.warextAudit-caseTitle, .warextAudit-caseMeta, .warextAudit-caseBadges, .warextAudit-snapshotHead, .warextAudit-snapshotMeta, .warextAudit-toolbar { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.warextAudit-caseMeta { margin-top: 5px; color: @xf-textColorMuted; font-size: 13px; }
.warextAudit-caseBadges { justify-content: flex-end; }
.warextAudit-badge { display: inline-flex; align-items: center; padding: 3px 8px; border-radius: 999px; background: @xf-contentAltBg; border: 1px solid @xf-borderColor; font-size: 12px; font-weight: 600; }
.warextAudit-badge--normal { color: @xf-textColorMuted; }
.warextAudit-badge--elevated { color: @xf-warningColor; }
.warextAudit-badge--critical, .warextAudit-badge--sensitive { color: @xf-errorColor; border-color: fade(@xf-errorColor, 45%); }
.warextAudit-badge--status { color: @xf-linkColor; }
.warextAudit-muted { color: @xf-textColorMuted; }
.warextAudit-toolbar { margin: 10px 0 15px; }
.warextAudit-detailGrid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 15px; }
.warextAudit-kv > div { display: grid; grid-template-columns: 150px 1fr; gap: 12px; padding: 10px 15px; border-bottom: 1px solid @xf-borderColor; }
.warextAudit-kv > div:last-child { border-bottom: 0; }
.warextAudit-json { margin: 0; padding: 14px; overflow: auto; max-height: 650px; white-space: pre-wrap; overflow-wrap: anywhere; background: @xf-contentAltBg; border-radius: @xf-borderRadiusSmall; font-family: monospace; font-size: 12px; line-height: 1.55; }
.warextAudit-snapshot { padding: 15px; border-bottom: 1px solid @xf-borderColor; }
.warextAudit-snapshot:last-child { border-bottom: 0; }
.warextAudit-snapshot.is-sensitive { box-shadow: inset 3px 0 0 @xf-errorColor; }
.warextAudit-snapshotHead { justify-content: space-between; margin-bottom: 8px; }
.warextAudit-snapshotMeta { margin-bottom: 10px; color: @xf-textColorMuted; font-size: 12px; }
.warextAudit-snapshotMeta code { word-break: break-all; }
.warextAudit-integrity { font-size: 12px; font-weight: 700; }
.warextAudit-integrity.is-valid { color: @xf-successColor; }
.warextAudit-integrity.is-invalid { color: @xf-errorColor; }
.warextAudit-simpleList { list-style: none; margin: 0; padding: 0; }
.warextAudit-simpleList li { display: flex; justify-content: space-between; gap: 12px; padding: 10px 15px; border-bottom: 1px solid @xf-borderColor; }
.warextAudit-simpleList li:last-child { border-bottom: 0; }

.warextAudit-reviewForm { margin: 0; }
.warextAudit-reviewGrid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; padding: 15px; }
.warextAudit-reviewGrid label > span, .warextAudit-reasonField > span { display: block; margin-bottom: 5px; font-weight: 600; }
.warextAudit-reasonField { display: block; padding: 0 15px 15px; }
.warextAudit-reviewForm .block-footer { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.warextAudit-reviewList { display: flex; flex-direction: column; }
.warextAudit-reviewCard, .warextAudit-revisionCard { padding: 14px 15px; border-bottom: 1px solid @xf-borderColor; }
.warextAudit-reviewCard:last-child, .warextAudit-revisionCard:last-child { border-bottom: 0; }
.warextAudit-reviewHead { display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap; }
.warextAudit-reviewHead > div { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.warextAudit-reviewRatings { display: flex; gap: 12px; flex-wrap: wrap; margin-top: 9px; color: @xf-textColorMuted; font-size: 13px; }
.warextAudit-reviewReason { margin-top: 10px; padding: 10px; background: @xf-contentAltBg; border-radius: @xf-borderRadiusSmall; white-space: pre-wrap; overflow-wrap: anywhere; }
.warextAudit-reviewFoot { display: flex; justify-content: space-between; gap: 12px; flex-wrap: wrap; margin-top: 9px; color: @xf-textColorMuted; font-size: 12px; }
.warextAudit-revisionCard { margin: 0; }
@media (max-width: 900px) {
    .warextAudit-stats, .warextAudit-filterGrid, .warextAudit-detailGrid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 650px) {
    .warextAudit-stats, .warextAudit-filterGrid, .warextAudit-detailGrid, .warextAudit-reviewGrid { grid-template-columns: 1fr; }
    .warextAudit-caseRow { align-items: flex-start; flex-direction: column; }
    .warextAudit-caseBadges { justify-content: flex-start; }
    .warextAudit-kv > div { grid-template-columns: 1fr; gap: 4px; }
}
.warextAudit-poolForm { display: grid; grid-template-columns: 1.2fr 160px 2fr; gap: 10px; padding: 15px; }
.warextAudit-poolList { display: flex; flex-direction: column; }
.warextAudit-poolRow { display: flex; justify-content: space-between; align-items: flex-start; gap: 15px; padding: 14px 15px; border-bottom: 1px solid @xf-borderColor; }
.warextAudit-poolRow:last-child { border-bottom: 0; }
.warextAudit-inlineForm { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
.warextAudit-conflictForm { display: grid; grid-template-columns: 160px 1fr auto; gap: 8px; margin-top: 10px; }
@media (max-width: 650px) { .warextAudit-poolForm, .warextAudit-conflictForm { grid-template-columns: 1fr; } .warextAudit-poolRow { flex-direction: column; } }

.warextAudit-reportActions{display:flex;gap:10px;flex-wrap:wrap;align-items:center}.warextAudit-customRange{display:flex;gap:8px;flex-wrap:wrap}.warextAudit-reportGrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px}.warextAudit-tableWrap{overflow:auto}.warextAudit-tableWrap .dataList-table{min-width:850px;width:100%}


.warextAudit-readableEvidence{display:flex;flex-direction:column;gap:14px}
.warextAudit-evidenceTop,.warextAudit-contentMeta{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.warextAudit-evidenceTop{justify-content:space-between}
.warextAudit-actionStrip,.warextAudit-reason,.warextAudit-contextTitle{padding:10px 12px;border:1px solid @xf-borderColor;border-radius:@xf-borderRadiusMedium;background:xf-intensify(@xf-contentBg,2%)}
.warextAudit-contextTitle{display:flex;gap:10px;align-items:center}.warextAudit-contextTitle span{color:@xf-textColorMuted}
.warextAudit-contentCard,.warextAudit-reportComment,.warextAudit-contextPost{padding:14px;border:1px solid @xf-borderColor;border-radius:@xf-borderRadiusMedium;background:@xf-contentBg}
.warextAudit-contentMeta{font-size:12px;color:@xf-textColorMuted;margin-bottom:8px}.warextAudit-contentMeta strong{font-size:14px;color:@xf-textColor}
.warextAudit-contentTitle{font-size:16px;font-weight:700;margin-bottom:8px}
.warextAudit-contentMessage{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.55}
.warextAudit-evidenceSection h3{margin:0 0 10px}.warextAudit-reportComment+.warextAudit-reportComment{margin-top:8px}.warextAudit-reportComment.is-report{border-left:3px solid @xf-paletteAccent2}
.warextAudit-contextDetails{border-top:1px solid @xf-borderColor;padding-top:10px}.warextAudit-contextDetails summary{cursor:pointer;font-weight:600}.warextAudit-contextPosts{display:grid;gap:8px;margin-top:10px}.warextAudit-contextPost.is-focus{box-shadow:inset 3px 0 0 @xf-paletteAccent2}
.warextAudit-technical>summary{cursor:pointer;list-style:none}.warextAudit-technical>summary::-webkit-details-marker{display:none}
